join school_day d on d.campus_id = x.campus and d.on_date = v.d::date
join period p on p.tenant_id = x.tenant and p.grade_code = 'K2' and p.starts_at = v.st::time
left join fortnight f on f.academic_year_id = x.year and f.number = v.n::int
left join plan_entry pe on pe.school_class_id = x.klass and pe.fortnight_id = f.id and pe.plan_key = v.k and pe.ord = v.o::int
on conflict do nothing;
-- after
select 'fortnight' as t, count(*) from fortnight where academic_year_id = (select year from k2_ctx)
union all select 'school_day', count(*) from school_day where campus_id = (select campus from k2_ctx)
union all select 'period', count(*) from period where tenant_id = (select tenant from k2_ctx)
union all select 'timetable_slot', count(*) from timetable_slot where school_class_id = (select klass from k2_ctx)
union all select 'plan_entry', count(*) from plan_entry where school_class_id = (select klass from k2_ctx)
union all select 'session', count(*) from session where school_class_id = (select klass from k2_ctx);
commit;
